import XCTest
@testable import HandyTools

/// RAR opens in File Opener (tier 2). The archives are from UnrarKit's own test data (BSD licence): two stored text
/// files; a compressed README with a good checksum, the same with a damaged one; and a password-locked archive.
final class RarTests: XCTestCase {
    private let twoFiles = Data(base64Encoded: "UmFyIRoHAM+QcwAADQAAAAAAAABPfnQgkDIADAAAAAwAAAACzdM3RcAE1kYdMA0AIAAAAHlvaG9ob193cy50eHQAsN8HiGhlbGxvICEhISB4RL1IdCCQLQAIAAAACAAAAAKur4f2zwTWRh0wCAAgAAAAbm9wdy50eHQA8PwgSmF5ZSBzaXIhxD17AEAHAA==")!
    private let goodCRC = Data(base64Encoded: "")!
    private let badCRC = Data(base64Encoded: "")!
    private let locked = Data(base64Encoded: "")!

    private func write(_ d: Data, _ name: String) throws -> URL {
        let u = FileManager.default.temporaryDirectory.appendingPathComponent(name); try d.write(to: u); return u
    }

    func testRarListsAndOpensItsFiles() throws {
        guard case .archive(let entries, let kind) = FileReaders.read(try write(twoFiles, "two.rar")) else { return XCTFail("a .rar should open") }
        XCTAssertEqual(kind, "RAR")
        XCTAssertEqual(Set(entries.map(\.name)), ["yohoho_ws.txt", "nopw.txt"])
        XCTAssertEqual(entries.first { $0.name == "yohoho_ws.txt" }?.data().map { String(decoding: $0, as: UTF8.self) }, "hello !!! xD")
        XCTAssertEqual(entries.first { $0.name == "nopw.txt" }?.data().map { String(decoding: $0, as: UTF8.self) }, "aye sir!")
    }

    func testCompressedFileComesOutWholeAndChecked() throws {
        guard case .archive(let entries, _) = FileReaders.read(try write(goodCRC, "good.rar")) else { return XCTFail("good.rar should open") }
        let readme = try XCTUnwrap(entries.first { $0.name == "README.md" })
        let d = try XCTUnwrap(readme.data(), "decompression failed")
        XCTAssertEqual(d.count, readme.size, "every byte, as the archive says")
    }

    func testDamagedFileIsNotHandedBack() throws {
        if case .archive(let entries, _) = FileReaders.read(try write(badCRC, "bad.rar")) {
            XCTAssertNil(entries.first { $0.name == "README.md" }?.data(), "a file that fails its checksum must not be shown as good")
        }
    }

    func testLockedArchiveSaysSo() throws {
        guard case .info(_, let detail, _) = FileReaders.read(try write(locked, "locked.rar")) else { return XCTFail("a locked .rar should explain itself") }
        XCTAssertTrue(detail.contains("password"), detail)
    }
}
